import http from 'k6/http';
import { check, sleep, fail } from 'k6';
import { textSummary } from 'https://jslib.k6.io/k6-summary/0.0.2/index.js';
import { htmlReport } from 'https://raw.githubusercontent.com/benc-uk/k6-reporter/main/dist/bundle.js';

/**
 * Generated by the k6-ramp-load-test skill.
 * Target: GET /en/classes on mrkhaldoon.com — the "All Subjects" page
 * (a Next.js server-rendered route, not a JSON API endpoint), so checks
 * validate a successful HTML response rather than JSON shape.
 * Auth flow reused from the earlier Khaldoon setup: NextAuth credentials
 * provider — GET /api/auth/csrf for a token, POST it + credentials as
 * form-urlencoded, session travels as cookies afterward.
 */

const BASE_URL = __ENV.BASE_URL || 'https://staging.mrkhaldoon.com';
const ALLOW_PROD = (__ENV.ALLOW_PROD || 'false').toLowerCase() === 'true';

// k6's JS runtime has no global URL/URLSearchParams — match the host as
// a plain string/regex instead of parsing it.
if (/^https?:\/\/([^/]*\.)?mrkhaldoon\.com(\/|$)/.test(BASE_URL) && !ALLOW_PROD) {
  fail(
    `Refusing to run against ${BASE_URL} — this looks like production. ` +
      `Point BASE_URL at staging, or set ALLOW_PROD=true if you really mean it.`
  );
}

// TEST_ACCOUNTS="email1:pw1,email2:pw2,email3:pw3"
const ACCOUNTS = (__ENV.TEST_ACCOUNTS || '')
  .split(',')
  .map((pair) => pair.trim())
  .filter(Boolean)
  .map((pair) => {
    const [email, password] = pair.split(':');
    return { email, password };
  });

if (ACCOUNTS.length === 0) {
  fail(
    'TEST_ACCOUNTS is required, e.g. -e TEST_ACCOUNTS="a@x.com:pw1,b@x.com:pw2,c@x.com:pw3"'
  );
}

// Computed by scripts/compute-ramp-stages.js for peak=1000, duration=180s.
const RAMP_STAGES = [
  { duration: '23s', target: 100 },
  { duration: '23s', target: 300 },
  { duration: '23s', target: 600 },
  { duration: '23s', target: 1000 },
  { duration: '54s', target: 1000 },
  { duration: '36s', target: 0 },
];

// Passing -e VUS and -e DURATION overrides the baked-in ramp with a flat,
// short verification run instead — WITHOUT this, those flags are silently
// ignored (k6 only reads options.stages here) and any "verification"
// command actually runs the full peak-VU ramp. Always use VUS/DURATION
// for a first check before the real run.
export const options = {
  stages: __ENV.VUS && __ENV.DURATION
    ? [{ duration: __ENV.DURATION, target: Number(__ENV.VUS) }]
    : RAMP_STAGES,
  thresholds: {
    http_req_failed: ['rate<0.01'],
    http_req_duration: ['p(95)<800'],
  },
};

function login(email, password) {
  const csrfRes = http.get(`${BASE_URL}/api/auth/csrf`);
  const csrfToken = csrfRes.json('csrfToken');

  const loginRes = http.post(
    `${BASE_URL}/api/auth/callback/credentials`,
    {
      email,
      password,
      redirect: 'false',
      csrfToken,
      callbackUrl: `${BASE_URL}/en/login`,
      json: 'true',
    },
    { cookies: csrfRes.cookies }
  );

  if (loginRes.status !== 200) {
    fail(`login failed for ${email}: ${loginRes.status} ${loginRes.body}`);
  }

  const allCookies = { ...csrfRes.cookies, ...loginRes.cookies };
  return Object.entries(allCookies)
    .map(([name, jar]) => `${name}=${jar[0].value}`)
    .join('; ');
}

// Per-VU session cache — each VU logs in once (its first iteration) as
// its round-robin-assigned account, then reuses that cookie afterward.
const vuSessions = {};

export default function () {
  const vuId = __VU;
  if (!vuSessions[vuId]) {
    const account = ACCOUNTS[(vuId - 1) % ACCOUNTS.length];
    vuSessions[vuId] = { account, cookieHeader: login(account.email, account.password) };
  }
  const { account, cookieHeader } = vuSessions[vuId];

  const res = http.get(`${BASE_URL}/en/classes`, {
    headers: { Cookie: cookieHeader },
    tags: { account: account.email },
  });

  check(res, {
    'status is 200': (r) => r.status === 200,
    'has body': (r) => r.body && r.body.length > 0,
  });

  sleep(1);
}

export function handleSummary(data) {
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  const report = htmlReport(data);
  return {
    stdout: textSummary(data, { indent: ' ', enableColors: true }),
    [`performance/reports/classes-page-load-report-${stamp}.html`]: report,
    'performance/classes-page-load-report-latest.html': report,
  };
}
